        "repositoryId": "uuid",
        "providerNumber": "integer",
        "url": "string",
        "headSha": "string",
        "baseSha": "string",
        "status": "enum(open|merged|closed)",
        "mergedSha": "string|null",
        "createdAt": "timestamp",
        "updatedAt": "timestamp",
